"""Explain legacy stack trace state, wrappers and weak defaults."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1957': ('길을 따라 지나온 장소를 적으려면 빈 공책과 기록 규칙이 필요해요. stack_trace는 그런 준비 정보를 묶은 카드예요.', '구조체의 저장 위치·최대 개수·실제 개수·건너뛸 개수를 구별합니다.', '빈 칸 4개를 그리고 max_entries=4라고 적으세요. 두 칸에 A와 B를 쓴 뒤 nr_entries=2라고 적으세요.', ['스택 추적은 함수들이 서로 부르며 지나온 경로를 주소로 모으는 일이에요. 여기서 주소는 코드가 있는 메모리 위치를 나타내요. struct stack_trace는 그 기록을 도울 여러 정보를 한데 묶은 구조체예요.', 'entries는 주소들을 넣을 배열의 위치를 가리켜요. 배열은 같은 종류의 값을 차례로 넣는 칸들이에요. entries 자체가 모든 기록을 담는 공책은 아니고, 공책이 어디 있는지 알려 주는 쪽지와 비슷해요.', 'max_entries는 준비된 배열에 최대 몇 개를 저장할 수 있는지 알려 줘요. nr_entries는 실제로 몇 개를 저장했는지예요. 네 칸을 준비하고 두 개를 썼다면 최대 개수는 4, 실제 개수는 2예요. 두 수를 혼동하면 쓰지 않은 칸까지 결과로 읽게 돼요.', 'skip은 처음에 몇 개를 건너뛰도록 요청할지 나타내요. 예를 들어 skip=1은 처음 항목 하나를 기록 대상에서 빼 달라는 뜻이에요. 저장 공간의 칸 수를 1로 만든다는 뜻은 아니에요.', '이 정의는 CONFIG_STACKTRACE가 켜져 있고 CONFIG_ARCH_STACKWALK가 꺼진 조건에서 사용해요. CONFIG 이름은 커널을 만들 때 선택하는 기능 설정이에요. 여기서 구형 방식이라고 부르는 것은 이 설정 쪽의 내부 연결 방식을 뜻해요.', '헤더 주석은 이 내부 함수를 공통 코드에서 직접 쓰지 말라고 안내해요. 공통 코드는 여러 기종에서 함께 쓰는 코드예요. 보통 stack_trace_save 같은 공개 함수를 사용하면 그 안에서 설정에 맞는 내부 방식으로 연결해 줘요. 이름이 비슷한 save_stack_trace와 순서를 잘 구별해요.'], [('네 칸짜리 기록 배열에서 max_entries=4는 무엇을 뜻하나요?', ['출력할 문장이 네 글자라는 뜻이에요', '주소를 최대 네 개 담을 수 있다는 뜻이에요'], '정답은 두 번째예요. max_entries는 배열에 넣을 항목의 최대 개수예요. 글자 수를 정하는 값이 아니며, 실제로 두 개만 저장했다면 nr_entries는 2예요.'), ('여러 기종이 함께 쓰는 코드에서 구형 내부 함수 save_stack_trace를 직접 쓰도록 권하나요?', ['아니요. 헤더는 공통 코드에서 내부 함수를 직접 쓰지 말라고 해요', '네. 모든 설정에서 이 내부 함수만 사용하면 돼요'], '정답은 첫 번째예요. 설정마다 내부 수집 방식이 달라질 수 있어요. 공개 함수 stack_trace_save가 그 차이를 연결하므로, 두 이름이 비슷하다고 같은 역할로 생각하지 않아요.')]), 'os1958': ('사진을 찍는 사람의 손이 사진에 나오면 빼고 싶을 수 있어요. 경로를 모으는 함수도 자기 자신에 해당하는 기록을 하나 더 건너뛰도록 요청해요.', '이름을 지정한 초기화와 실제 저장 개수 반환을 이해합니다.', 'skipnr=0이면 skip=1, skipnr=2이면 skip=3을 적으세요. 용량 4에 두 개를 저장했다면 반환값은 2라고 적으세요.', ['여기서는 CONFIG_ARCH_STACKWALK가 꺼진 쪽의 stack_trace_save를 읽어요. 이 함수는 기록할 배열 store, 그 배열의 용량 size, 처음 건너뛸 개수 skipnr를 받아요. 용량은 주소를 담을 칸 수예요.', 'struct stack_trace trace = { ... }는 수집 준비 카드 trace를 만들면서 처음 값을 넣는 코드예요. .entries = store는 카드의 entries 항목에 배열 위치를 넣어요. 점 뒤에 항목 이름을 쓰므로 어느 칸에 넣는지 알 수 있어요.', '.max_entries = size는 배열 용량을 전달해요. .skip = skipnr + 1은 요청받은 건너뛰기 수에 1을 더해요. 이 함수를 거치며 생기는 자기 자신의 기록도 빼기 위한 준비예요. 보통의 작은 값 예로 skipnr가 0이면 skip은 1이에요.', 'nr_entries는 이 중괄호 초기화에 따로 쓰지 않았으므로 0으로 시작해요. C에서 구조체를 이런 식으로 일부 항목만 초기화하면 나머지 정수 항목은 0이 돼요. 초기화 없이 선언한 모든 지역 변수도 저절로 0이 된다는 뜻은 아니에요.', 'save_stack_trace(&trace)는 준비 카드의 주소를 내부 함수에 건네요. &는 그 물건이 있는 위치를 얻는 표시예요. 내부 함수가 trace를 통해 결과 개수를 적으면, 호출한 쪽에서도 같은 카드의 바뀐 값을 볼 수 있어요.', '마지막 return trace.nr_entries는 실제 저장 개수를 돌려줘요. 최대 네 개를 넣을 수 있어도 두 개만 찾았다면 2예요. max_entries를 돌려주면 빈 칸까지 채운 것처럼 오해할 수 있으므로 실제 개수를 사용해요.'], [('이 구형 wrapper에 skipnr=0을 주면 내부 카드의 skip은 얼마인가요?', ['0이에요', '1이에요'], '정답은 두 번째예요. 코드가 skipnr + 1을 넣으므로 0+1=1이에요. 사용자의 요청 0을 그대로 복사하는 것이 아니라 이 함수 자신의 기록을 위한 한 개를 더해요.'), ('배열 용량이 4이고 실제 저장된 주소가 2개라면 무엇을 반환하나요?', ['실제 개수 nr_entries인 2예요', '최대 개수 max_entries인 4예요'], '정답은 첫 번째예요. return 뒤에는 trace.nr_entries가 있어요. 4는 준비한 칸 수이고 결과가 실제로 채워진 칸 수는 2예요.')]), 'os1959': ('담당자가 없을 때 안내문만 보여 주는 기본 창구를 생각해 보세요. 안내문이 나왔다고 부탁한 일이 끝난 것은 아니에요.', 'weak 기본 함수와 실제 기능 구현을 구별합니다.', '기본 함수 선택 → 경고 → 기록 개수 그대로를 그리세요. 실제 구현 선택은 프로그램을 연결할 때 결정하는 별도 가지로 그리세요.', ['이 구형 경로에는 __weak가 붙은 save_stack_trace_tsk와 save_stack_trace_regs의 기본 함수가 있어요. tsk 쪽은 태스크, 즉 커널이 관리하는 실행 주체를 입력받고, regs 쪽은 저장된 CPU 실행 정보를 입력받아요.', '__weak는 약한 정의라는 표시예요. 커널을 만드는 과정에는 여러 코드 조각의 함수 이름을 연결하는 링크 단계가 있어요. 이때 같은 이름의 일반적인 강한 정의가 함께 제공되면 그것이 이 약한 기본 정의를 대신할 수 있어요.', '기본 함수 본문에는 WARN_ONCE가 있고 아직 구현되지 않았다는 경고를 내요. 이 본문은 출력 배열에 주소를 넣지도 않고 trace의 nr_entries를 늘리지도 않아요. 함수 이름에 save가 들어 있다고 실제 저장 작업이 있다고 판단하면 안 돼요.', '호출 전 카드의 nr_entries가 0이었고 이 기본 함수에서 돌아와 실행을 계속한다면 개수는 여전히 0이에요. 주소를 성공적으로 찾았다는 뜻이 아니라 이 기본 본문이 개수를 바꾸지 않았기 때문이에요.', 'WARN_ONCE는 같은 경고를 계속 쏟아 내지 않도록 한 번 경고하는 장치를 사용해요. 종이에 함수 호출 횟수를 두 번 표시했다고 실제 커널 로그도 두 번 찍힌다는 뜻은 아니에요. 경고의 동작과 단순한 호출 횟수는 다른 것이에요.', 'CPU별 구현이 연결되었다면 그 구현의 본문을 따로 읽어야 해요. 실행 중 첫 호출은 기본 함수, 다음 호출은 자동으로 실제 함수로 바뀌는 규칙이 아니에요. 어떤 함수가 연결되었는지와 그 함수가 무엇을 하는지를 나누어 확인해요.'], [('여기서 읽은 weak 기본 함수가 실제로 하는 일은 무엇인가요?', ['배열을 호출 경로 주소로 가득 채워요', '미구현 경고를 내며 주소와 개수를 채우지 않아요'], '정답은 두 번째예요. 본문에는 경고 호출이 있고 저장 코드가 없어요. CPU별 실제 구현이 대신 연결된 경우의 동작까지 이 기본 본문으로 판단하면 안 돼요.'), ('종이 예제에서 경고 함수 호출을 세었다면 실제 커널의 WARN_ONCE 동작까지 확인한 건가요?', ['아니요. 호출 횟수와 실제 경고 출력 제어는 따로 확인해야 해요', '네. 세 번 호출했다고 적으면 실제 로그도 반드시 세 줄이에요'], '정답은 첫 번째예요. WARN_ONCE는 반복 출력을 제어해요. 단순한 횟수 세기는 실제 커널의 경고 처리나 링크에서 선택한 구현을 실행해 본 검사가 아니에요.')]), 'os1960': ('자기 발자국을 찾을 때는 지금 하는 찾기 동작도 경로에 들어갈 수 있어요. 다른 사람의 경로를 찾을 때와 준비가 조금 달라요.', '현재 태스크 비교와 구형 wrapper의 책임 범위를 이해합니다.', 'skipnr=2라고 놓고 current==task가 참이면 3, 거짓이면 2를 적으세요.', ['구형 stack_trace_save_tsk는 지정한 태스크의 호출 경로를 모으도록 내부 함수를 부르는 연결 함수예요. 이런 연결 함수를 wrapper라고 해요. task는 조사할 태스크이고 current는 지금 이 코드를 실행하는 태스크예요.', '먼저 trace 카드에 배열 위치 store와 용량 size를 넣어요. nr_entries는 중괄호 초기화에서 생략했으므로 0으로 시작해요. 따라서 결과를 담기 전의 개수와 배열 용량을 구별할 수 있어요.', '건너뛸 개수는 skipnr + (current == task)예요. ==는 두 값이 같은지 비교해요. C에서는 이 비교가 참이면 1, 거짓이면 0이 되므로 조사 대상이 자기 자신이면 한 개를 더 건너뛰도록 요청해요.', '예를 들어 skipnr=2일 때 자기 자신을 조사하면 2+1=3이에요. 다른 태스크라면 2+0=2예요. 다른 태스크의 경로를 모두 지운다는 뜻은 아니고, 시작에서 건너뛸 개수를 준비하는 계산이에요.', '다음은 save_stack_trace_tsk(task, &trace)를 호출하고 trace.nr_entries를 돌려주는 순서예요. 이 wrapper 본문에는 try_get_task_stack이나 put_task_stack 호출이 없어요. 앞서 배운 CONFIG_ARCH_STACKWALK 쪽 wrapper의 스택 수명 확보·반납 코드를 여기에 있다고 옮겨 읽으면 안 돼요.', '그렇다고 모든 기종에서 스택 수명 보호가 필요 없다는 결론도 낼 수 없어요. 수명은 읽는 동안 그 메모리가 사라지지 않는 기간을 뜻해요. 실제로 연결된 CPU별 내부 함수와 호출하는 쪽이 어떤 조건을 마련하는지 확인해야 책임을 알 수 있어요.'], [('이 구형 wrapper 본문이 직접 try_get_task_stack을 부르나요?', ['네. 모든 방식의 wrapper가 반드시 직접 불러요', '아니요. 이 본문은 카드 준비 뒤 내부 수집 함수를 불러요'], '정답은 두 번째예요. 실제 본문에는 해당 호출이 없어요. 다른 설정 쪽에 있는 코드를 이 본문에도 있다고 가정하면 안 되며, 전체 수명 보호는 관련 호출 경로에서 확인해야 해요.'), ('skipnr=2일 때 current와 task가 같으면 내부 skip은 얼마인가요?', ['3이에요. 같은지 비교한 결과 1을 더해요', '다른 태스크의 주소를 모두 지워요'], '정답은 첫 번째예요. 2+(참을 나타내는 1)=3이에요. 이 식은 개수를 계산할 뿐 다른 태스크의 기록을 지우는 명령이 아니에요.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_485.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
